t.script:
const TEMPLATE_ID = ;
const REQUEST_ID = ;
const ACCESS_TOKEN = '';
const SIGN_ITEMS = ;

const pdfjsLib = window['pdfjs-dist/build/pdf'];
pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

let pdfDoc = null;
let pageNum = 1;
let pageRendering = false;
let pageNumPending = null;
let canvasList = [];
let signItemInputs = {};

async function renderPDF(url, canvasContainer) {
    const loadingTask = pdfjsLib.getDocument(url);
    pdfDoc = await loadingTask.promise;
    for (let i = 1; i <= pdfDoc.numPages; i++) {
        await renderPage(i, canvasContainer);
    }
    renderSignItems();
}

async function renderPage(num, canvasContainer) {
    const page = await pdfDoc.getPage(num);
    const scale = 1.5;
    const viewport = page.getViewport({scale: scale});
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.height = viewport.height;
    canvas.width = viewport.width;
    canvas.style.width = '100%';
    canvasContainer.appendChild(canvas);
    canvasList.push({canvas, viewport, pageNum: num});
    const renderContext = {
        canvasContext: ctx,
        viewport: viewport
    };
    await page.render(renderContext).promise;
}

function renderSignItems() {
    SIGN_ITEMS.forEach(item => {
        const pageCanvasData = canvasList.find(c => c.pageNum === item.page);
        if (!pageCanvasData) return;
        const container = document.createElement('div');
        container.className = 'sign-item';
        container.style.position = 'absolute';
        container.style.left = (item.posX * 100) + '%';
        container.style.top = (item.posY * 100) + '%';
        container.style.width = (item.width * 100) + '%';
        container.style.height = (item.height * 100) + '%';
        container.style.border = '1px dashed #000';
        container.style.zIndex = 10;
        container.style.boxSizing = 'border-box';
        if (['signature', 'initial'].includes(item.type)) {
            container.addEventListener('click', () => openSignaturePad(item.id));
            container.innerHTML = '<span style="color: #888; margin:auto; display: flex; justify-content: center; align-items: center; height: 100%;">Click to sign</span>';
        } else if (item.type === 'checkbox') {
            container.innerHTML = '<input type="checkbox" style="margin: auto; display: block; transform: scale(2);">';
        } else {
            container.innerHTML = '<input type="text" style="width: 100%; height: 100%; box-sizing: border-box; padding: 5px;">';
        }
        const canvas = pageCanvasData.canvas;
        canvas.style.position = 'relative';
        canvas.parentNode.style.position = 'relative';
        canvas.parentNode.insertBefore(container, canvas.nextSibling);
        signItemInputs[item.id] = { type: item.type, el: container };
    });
}

let currentSignItemId = null;
let signatureData = {};

function openSignaturePad(itemId) {
    currentSignItemId = itemId;
    const modal = document.createElement('div');
    modal.id = 'signature-modal';
    modal.className = 'modal';
    modal.innerHTML = `
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Sign Here</h5>
                    <button type="button" class="close" onclick="closeSignaturePad()">
                        <span>&times;</span>
                    </button>
                </div>
                <div class="modal-body">
                    <canvas id="signature-pad" style="border:1px solid #000; width:100%; height:200px;"></canvas>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn-secondary" onclick="closeSignaturePad()">Cancel</button>
                    <button type="button" class="btn-primary" onclick="saveSignature()">Save</button>
                </div>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    const canvas = modal.querySelector('#signature-pad');
    const ctx = canvas.getContext('2d');
    let isDrawing = false;
    let lastX = 0;
    let lastY = 0;
    canvas.addEventListener('mousedown', e => {
        isDrawing = true;
        [lastX, lastY] = getMousePos(canvas, e);
    });
    canvas.addEventListener('mouseup', () => isDrawing = false);
    canvas.addEventListener('mouseout', () => isDrawing = false);
    canvas.addEventListener('mousemove', e => {
        if (isDrawing) {
            const [x, y] = getMousePos(canvas, e);
            drawLine(ctx, lastX, lastY, x, y);
            [lastX, lastY] = [x, y];
        }
    });
}

window.openSignaturePad = openSignaturePad;

function getMousePos(canvas, evt) {
    const rect = canvas.getBoundingClientRect();
    return [
        evt.clientX - rect.left,
        evt.clientY - rect.top
    ];
}

function drawLine(ctx, x1, y1, x2, y2) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#000';
    ctx.stroke();
}

function saveSignature() {
    if (!currentSignItemId) return;
    const modal = document.getElementById('signature-modal');
    const canvas = modal.querySelector('#signature-pad');
    const dataURL = canvas.toDataURL('image/png');
    signatureData[currentSignItemId] = dataURL;
    const signItem = signItemInputs[currentSignItemId];
    if (signItem) {
        const img = document.createElement('img');
        img.src = dataURL;
        img.style.width = '100%';
        img.style.height = '100%';
        signItem.el.innerHTML = '';
        signItem.el.appendChild(img);
    }
    closeSignaturePad();
}

window.saveSignature = saveSignature;

function closeSignaturePad() {
    const modal = document.getElementById('signature-modal');
    if (modal) modal.remove();
}

window.closeSignaturePad = closeSignaturePad;

document.getElementById('o_sign_submit').addEventListener('click', async () => {
    const values = {};
    Object.keys(signItemInputs).forEach(key => {
        const item = signItemInputs[key];
        if (['signature', 'initial'].includes(item.type)) {
            values[key] = signatureData[key];
        } else if (item.type === 'checkbox') {
            values[key] = item.el.querySelector('input').checked ? 'on' : 'off';
        } else {
            values[key] = item.el.querySelector('input').value;
        }
    });
    const formData = new FormData();
    formData.append('data', JSON.stringify(values));
    const response = await fetch('/sign/submit/' + REQUEST_ID + '/' + ACCESS_TOKEN, {
        method: 'POST',
        body: formData
    });
    const result = await response.json();
    if (result.success) {
        window.location.reload();
    }
});

renderPDF('/sign/template/' + TEMPLATE_ID + '/pdf', document.getElementById('o_sign_root'));
